// ── WF6: Combinar stats + errores recientes + entregas recientes ──────────
const stats   = $('PG Stats').first().json;
const errRows = $('PG Errores Recientes').all().map(i => i.json);
const subRows = $input.all().map(i => i.json);

const num = v => Number(v) || 0;

return [{
  json: {
    ok: true,
    timestamp: new Date().toISOString(),
    attendance: {
      total: num(stats.att_total), present: num(stats.att_present),
      absent: num(stats.att_absent), late: num(stats.att_late),
      rate: num(stats.att_rate)
    },
    submissions: {
      total: num(stats.sub_total), on_time: num(stats.sub_on_time),
      late: num(stats.sub_late), missing: num(stats.sub_missing)
    },
    feedback: {
      total: num(stats.fb_total), avg_grade: num(stats.fb_avg),
      passing: num(stats.fb_passing), failing: num(stats.fb_failing)
    },
    system: {
      errors: num(stats.err_total), reports: num(stats.rpt_total),
      notifications: num(stats.notif_total)
    },
    recent_errors: errRows,
    recent_submissions: subRows
  }
}];
